(()=>{'use strict';
const $=id=>document.getElementById(id),c=$('game'),g=c.getContext('2d'),keys=new Set();
let state='menu',fighters=[],shots=[],sparks=[],round=1,time=60,elapsed=0,last=0,shake=0,announcement='',annTime=0,transition=0,audio=false,ac;
const ground=514;
function tone(f=160,d=.1,type='square'){if(!audio)return;try{ac??=new(window.AudioContext||window.webkitAudioContext)();ac.resume();const o=ac.createOscillator(),v=ac.createGain();o.type=type;o.frequency.setValueAtTime(f,ac.currentTime);o.frequency.exponentialRampToValueAtTime(35,ac.currentTime+d);v.gain.setValueAtTime(.07,ac.currentTime);v.gain.exponentialRampToValueAtTime(.001,ac.currentTime+d);o.connect(v);v.connect(ac.destination);o.start();o.stop(ac.currentTime+d)}catch(e){}}
function fighter(i){return {i,x:i?880:320,y:ground,vy:0,face:i?-1:1,hp:100,wins:0,energy:100,attack:null,cool:0,stun:0,block:false,walk:0,ai:0,color:i?'#a5e0e9':'#f3ba6c'};}
function resetRound(){const wins=fighters.map(f=>f.wins);fighters=[fighter(0),fighter(1)];fighters.forEach((f,i)=>f.wins=wins[i]||0);shots=[];sparks=[];time=60;elapsed=0;transition=0;announcement='ROUND '+round;annTime=1.5;updateHud();}
function start(){keys.clear();round=1;fighters=[];resetRound();state='fight';$('overlay').classList.add('hidden');$('pause').textContent='Ⅱ PAUSA';$('status').textContent='Combatti! Il primo a vincere 2 round vince.';tone(360,.3,'sawtooth');}
function overlay(label,title,txt,button){$('overLabel').textContent=label;$('overTitle').innerHTML=title;$('overText').textContent=txt;$('play').innerHTML=button+' <span>↗</span>';$('overlay').classList.remove('hidden');}
function pause(){if(state==='fight'){state='pause';keys.clear();overlay('PRENDI FIATO','IN PAUSA','L’arena ti aspetta.','RIPRENDI');$('pause').textContent='▶ RIPRENDI';}else if(state==='pause'){state='fight';$('overlay').classList.add('hidden');$('pause').textContent='Ⅱ PAUSA';}}
function attack(f,type){if(state!=='fight'||f.cool>0||f.stun>0||f.attack||f.block)return;if(type==='special'&&f.energy<45)return;f.attack={type,t:0,hit:false};f.cool=type==='kick'?.65:type==='special'?.85:.4;if(type==='special'){f.energy-=45;tone(420,.25,'sawtooth');}else tone(type==='kick'?95:150,.08,'triangle');}
function hit(a,b,dmg,knock){if(b.hp<=0)return;const guarded=b.block&&b.y===ground&&b.face===-a.face;b.hp=Math.max(0,b.hp-(guarded?dmg*.18:dmg));b.stun=guarded?.08:.24;b.x+=a.face*(guarded?knock*.2:knock);shake=guarded?3:9;for(let i=0;i<14;i++)sparks.push({x:b.x-a.face*15,y:b.y-90,vx:(Math.random()-.5)*450,vy:(Math.random()-.5)*450,t:.3,color:guarded?'#dcefff':'#ffc47c'});tone(guarded?240:70,.16);if(b.hp===0)finishRound();}
function finishRound(){state='round';let win=fighters[0].hp===fighters[1].hp?-1:fighters[0].hp>fighters[1].hp?0:1;if(win>=0)fighters[win].wins++;announcement=win<0?'PAREGGIO':(win===0?'EMBER':'FROST')+' VINCE';annTime=3;transition=3;updateHud();}
function updateHud(){fighters.forEach((f,i)=>{$('hp'+(i+1)).style.width=f.hp+'%';$('wins'+(i+1)).textContent=Array.from({length:2},(_,n)=>n<f.wins?'●':'○').join(' ')});$('timer').textContent=String(Math.ceil(time)).padStart(2,'0');$('round').textContent='ROUND '+String(round).padStart(2,'0');}
function input(f,dt){let left,right,jump,block;if(f.i===1&&$('mode').value==='cpu'){f.ai-=dt;let dist=Math.abs(f.x-fighters[0].x);left=dist>100&&f.x>fighters[0].x;right=dist>100&&f.x<fighters[0].x;block=fighters[0].attack&&dist<170&&Math.random()<.85;if(f.ai<=0){f.ai=.25+Math.random()*.45;if(dist<150)attack(f,Math.random()<.48?'punch':'kick');else if(dist>230&&Math.random()<.4)attack(f,'special');jump=Math.random()<.13;}}else{const codes=f.i?['arrowleft','arrowright','arrowup','arrowdown']:['a','d','w','s'];[left,right,jump,block]=codes.map(k=>keys.has(k));}f.block=!!block&&!f.attack&&f.y===ground;f.face=f.x<fighters[1-f.i].x?1:-1;if(f.stun<=0&&!f.attack){const move=(right?1:0)-(left?1:0);if(!f.block){f.x+=move*250*dt;f.walk+=Math.abs(move)*dt*11;if(jump&&f.y===ground){f.vy=-650;tone(220,.1,'triangle');}}} }
function step(dt){sparks.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=600*dt;p.t-=dt});sparks=sparks.filter(p=>p.t>0);shake=Math.max(0,shake-dt*50);annTime=Math.max(0,annTime-dt);
if(state==='round'){transition-=dt;if(transition<=0){const winner=fighters.find(f=>f.wins>=2);if(winner){state='over';overlay('MATCH COMPLETATO',winner.i===0?'EMBER<br>TRIONFA.':'FROST<br>TRIONFA.',winner.i===0?'L’arena è tua. Sei pronto a difendere il titolo?':'Un altro incontro. Un’altra occasione.','RIVINCITA');$('status').textContent=(winner.i?'Frost':'Ember')+' conquista il match.';}else{round++;resetRound();state='fight';}}return;}
if(state!=='fight')return;elapsed+=dt;if(elapsed>1.2)time=Math.max(0,time-dt);if(time===0){finishRound();return;}
fighters.forEach(f=>{f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);f.energy=Math.min(100,f.energy+dt*10);input(f,dt);f.vy+=1600*dt;f.y+=f.vy*dt;if(f.y>=ground){f.y=ground;f.vy=0;}f.x=Math.max(65,Math.min(1135,f.x));if(f.attack){const a=f.attack;a.t+=dt;const b=fighters[1-f.i];if(a.type==='special'&&!a.hit&&a.t>.17){a.hit=true;shots.push({x:f.x+f.face*55,y:f.y-92,v:f.face*620,owner:f.i,t:2});}else if(a.type!=='special'&&!a.hit&&a.t>.1){a.hit=true;const range=a.type==='kick'?153:107;if(Math.abs(b.x-f.x)<range&&Math.abs(b.y-f.y)<90&&(b.x-f.x)*f.face>0)hit(f,b,a.type==='kick'?13:8,a.type==='kick'?38:23);}if(a.t>(a.type==='special'?.48:.32))f.attack=null;}});
const [a,b]=fighters;if(Math.abs(a.x-b.x)<55&&Math.abs(a.y-b.y)<100){const m=(a.x+b.x)/2,s=a.x<b.x?1:-1;a.x=m-s*28;b.x=m+s*28;}
shots.forEach(s=>{s.x+=s.v*dt;s.t-=dt;const b=fighters[1-s.owner];if(Math.abs(s.x-b.x)<36&&Math.abs(s.y-(b.y-87))<58){hit(fighters[s.owner],b,18,50);s.t=0;}});shots=shots.filter(s=>s.t>0&&s.x>-40&&s.x<1240);updateHud();}
function rect(x,y,w,h,col){g.fillStyle=col;g.fillRect(x,y,w,h)}
function background(t){const bg=g.createLinearGradient(0,0,0,ground);bg.addColorStop(0,'#191621');bg.addColorStop(.65,'#47303c');bg.addColorStop(1,'#76504a');g.fillStyle=bg;g.fillRect(0,0,1200,620);
g.fillStyle='#c3a19a';g.globalAlpha=.5;g.beginPath();g.arc(600,167,66,0,7);g.fill();g.globalAlpha=1;
for(let layer=0;layer<2;layer++){g.fillStyle=layer?'#382532':'#2e2533';g.beginPath();g.moveTo(0,340);for(let x=0;x<=1240;x+=40)g.lineTo(x,270+Math.sin(x*.012+layer)*45+Math.cos(x*.032)*25+layer*50);g.lineTo(1200,520);g.lineTo(0,520);g.fill();}
// Temple roof, stone pillars and shrine silhouettes.
rect(400,288,400,170,'#201c27');rect(430,300,340,150,'#33232f');for(let x=446;x<780;x+=44)rect(x,302,14,154,'#1e1c25');
g.fillStyle='#191923';g.beginPath();g.moveTo(350,292);g.quadraticCurveTo(475,280,600,207);g.quadraticCurveTo(725,280,850,292);g.lineTo(800,309);g.lineTo(400,309);g.closePath();g.fill();rect(383,309,435,10,'#75504b');
for(const x of [125,1000]){rect(x-15,135,100,22,'#171620');rect(x,157,65,300,'#201d27');rect(x+8,160,9,290,'#45303b');rect(x-15,448,95,30,'#191722');rect(x-24,476,114,15,'#29212b');}
for(const x of [260,940]){rect(x-7,368,14,104,'#211b25');rect(x-20,368,40,9,'#8e5b45');const flame=g.createRadialGradient(x,345,3,x,345,70);flame.addColorStop(0,'#ffb76380');flame.addColorStop(1,'#ffb76300');g.fillStyle=flame;g.fillRect(x-70,275,140,140);g.fillStyle='#f3a45a';g.beginPath();g.moveTo(x-11,367);g.quadraticCurveTo(x-19,348,x+Math.sin(t*9)*5,323);g.quadraticCurveTo(x+20,351,x+11,367);g.fill();}
rect(0,491,1200,18,'#3e3037');rect(0,509,1200,111,'#211c24');for(let y=520;y<620;y+=25){rect(0,y,1200,1,'#5d42443d');for(let x=(y%2)*70;x<1200;x+=140)rect(x,y,1,25,'#5d42443d');}rect(0,508,1200,2,'#aa786755');
for(let i=0;i<30;i++){let x=(i*137+t*(10+i%4))%1200,y=190+(i*71)%310;g.globalAlpha=.12+(Math.sin(t+i)+1)*.1;rect(x,y,2,2,'#e8b66b');}g.globalAlpha=1;}
function drawFighter(f,t){g.save();g.translate(f.x,f.y);g.fillStyle='#09090d66';g.beginPath();g.ellipse(0,3,48,9,0,0,7);g.fill();g.scale(f.face,1);if(f.hp<=0){g.translate(0,-15);g.rotate(-1.3);}let crouch=f.block?25:0,bob=f.y===ground?Math.sin(t*4+f.i)*3:0;g.translate(0,crouch+bob);const a=f.attack,type=a?.type,stretch=a?Math.sin(Math.min(1,a.t/.28)*Math.PI):0;g.strokeStyle=f.stun>0?'#fff':f.color;g.lineWidth=10;g.lineCap='round';g.lineJoin='round';g.shadowColor=f.color;g.shadowBlur=8;
function line(pts){g.beginPath();pts.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.stroke();}
g.beginPath();g.arc(0,-142,18,0,7);g.stroke();line([[0,-121],[-4,-74],[0,-56]]);
const stride=Math.sin(f.walk)*14;line([[0,-56],[-23-stride,-29],[-30-stride, -crouch]]);if(type==='kick')line([[0,-56],[45*stretch,-65],[115*stretch,-81]]);else line([[0,-56],[22+stride,-32],[33+stride,-crouch]]);
if(f.block){line([[0,-111],[28,-103],[30,-140]]);line([[-2,-108],[12,-87],[38,-117]]);}else {line([[0,-111],[-24,-89],[5,-83]]);line([[0,-110],[27+stretch*35,-102],[type==='punch'?40+stretch*65:38,type==='special'?-100:-118]]);}g.shadowBlur=0;
// Headband, belt, fist and shin wraps.
g.strokeStyle=f.i?'#487d9d':'#a45136';g.lineWidth=6;line([[-15,-147],[15,-147]]);line([[-6,-72],[6,-72]]);line([[-14,-146],[-32-Math.sin(t*7)*6,-132]]);
g.restore();g.fillStyle='#211b28';g.fillRect(f.x-34,f.y+16,68,4);g.fillStyle=f.color;g.fillRect(f.x-34,f.y+16,68*f.energy/100,4);}
function draw(t){g.save();g.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);background(t);fighters.forEach(f=>drawFighter(f,t));shots.forEach(s=>{const col=fighters[s.owner].color;g.shadowBlur=25;g.shadowColor=col;g.strokeStyle=col;g.lineWidth=5;g.beginPath();g.moveTo(s.x-Math.sign(s.v)*45,s.y);g.lineTo(s.x,s.y);g.stroke();g.fillStyle='#fff2d6';g.beginPath();g.ellipse(s.x,s.y,17,12,0,0,7);g.fill();g.shadowBlur=0;});sparks.forEach(p=>{g.globalAlpha=p.t/.3;rect(p.x,p.y,5,5,p.color)});g.globalAlpha=1;
if(annTime>0&&(state==='fight'||state==='round')){g.textAlign='center';g.shadowBlur=20;g.shadowColor='#000';g.fillStyle='#f5c87f';g.font='800 64px "Barlow Condensed", Impact, sans-serif';g.fillText(annTime<.6&&state==='fight'?'FIGHT!':announcement,600,270);g.shadowBlur=0;}g.restore();}
function loop(ts){const dt=Math.min((ts-last)/1000||.016,.035);last=ts;step(dt);draw(ts/1000);requestAnimationFrame(loop);}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(e.target.tagName==='SELECT')return;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(e.repeat)return;keys.add(k);if(k==='enter'){state==='pause'?pause():['menu','over'].includes(state)&&start();}if(k==='escape')pause();const attacks={j:[0,'punch'],k:[0,'kick'],l:[0,'special'],'1':[1,'punch'],'2':[1,'kick'],'3':[1,'special']};if(attacks[k]&&state==='fight'){const [i,a]=attacks[k];if(i===0||$('mode').value==='duo')attack(fighters[i],a);}});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();if(state==='fight')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='fight')pause()});
$('play').onclick=()=>state==='pause'?pause():start();$('pause').onclick=pause;$('restart').onclick=start;$('mode').onchange=()=>{$('p2tag').textContent=$('mode').value==='cpu'?'CPU':'GIOCATORE 2';state='menu';keys.clear();fighters=[fighter(0),fighter(1)];updateHud();overlay('SCEGLI LA TUA SFIDA','PRONTO A<br>COMBATTERE?','Il primo a vincere 2 round conquista l’arena.','ENTRA NELL’ARENA');};$('sound').onclick=()=>{audio=!audio;$('sound').textContent=audio?'AUDIO ON':'AUDIO OFF';$('sound').setAttribute('aria-label',audio?'Disattiva audio':'Attiva audio');tone(300,.15,'triangle')};
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);const k=b.dataset.key;keys.add(k);if(['j','k','l'].includes(k))attack(fighters[0],{j:'punch',k:'kick',l:'special'}[k]);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);});
fighters=[fighter(0),fighter(1)];updateHud();requestAnimationFrame(loop);
})();
